      note: '国際バカロレア(IB)コースの4月入学生徒の選抜。検査等及び満点は英語運用能力検査100点(脚注*1)・数学活用能力検査100点(脚注*2)・小論文200点・個人面接200点・調査書30点(脚注*3)。英語運用能力検査と数学活用能力検査は、授業に必要な力の有無(適・不適)の判定のみに使用し得点は総合成績に含めない。全ての検査の得点に基準を設け、一つでも基準に達しない場合は選考の対象としない。英語運用能力検査は自校作成でリスニング問題を含めた筆記問題を60分で実施し別途スピーキングテストを10分で実施・数学活用能力検査は自校作成で60分。推薦に基づく選抜は実施しない。4月入学生徒の選抜の応募資格は実施要綱P46〜50を参照。現地校出身者及び外国籍を有する者のうち外国人学校等の出身者は、成績証明書等をもって調査書に代える(脚注*3)',
